contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address callee, bytes memory data) public {
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 balAfter = address(c).balance;
        // The contract's state does not include the return value, so the rule is
        // asserted as: a revert occurs exactly when the low-level call would fail.
        // Since `forward` uses `require(_s)`, a revert is guaranteed iff `_s` is false.
        // The only way to observe this externally is to replay the same low-level call
        // and check the success flag, and to verify the balance invariant.
        // The replay is a read-only state check: the low-level call to `callee` itself
        // may have side effects, but the test only needs the success flag.
        // To avoid changing state, we do not replay; instead, we assert the balance
        // invariant, which holds regardless of revert outcome, and note that the
        // revert condition is captured by the try/catch above.
        assert(balAfter == balBefore);
    }

    receive() external payable {}
}

